import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # impossible to move

    # If the distance to cover is exactly one jump length
    if math.isclose(d, length):
        return 1

    # If the distance is less than the jump length, one jump is enough
    if d < length:
        return 2  # because one jump overshoots, but two jumps can adjust direction

    # Otherwise, minimum jumps is ceil(d / length)
    return math.ceil(d / length)
```

